// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address depositor) public {
        vm.assume(depositor != address(0));
        amount = bound(amount, 0, type(uint256).max / 2);
        vm.deal(depositor, amount);
        vm.prank(depositor);
        (bool ok,) = address(c).call{value: amount}("");
        assertTrue(ok);
        assertTrue(c.depositsCount() == 1, "one deposit must increment counter by exactly 1");
    }
}
